ExportDialog::~ExportDialog(){if(progress_)progress_->cancel=true;watcher_.waitForFinished();}
void ExportDialog::reject(){if(watcher_.isRunning()){progress_->cancel=true;status_->setText("Canceling export…");return;}QDialog::reject();}
QVector<ExportMesh> ExportDialog::selectedMeshes()const{QVector<ExportMesh> result;for(int i=0;i<entries_.size();++i)if(meshes_->topLevelItem(i)->checkState(0)==Qt::Checked){const auto &e=entries_[i];result.append({e.name,e.source,e.data});}return result;}
ModelExportOptions ExportDialog::options()const{ModelExportOptions o;o.format=ModelFormat(format_->currentData().toInt());o.scale=scale_->value();for(int i=0;i<3;++i){o.axes[i]=QString("XYZ").indexOf(axes_->currentText()[i]);o.negate[i]=negate_[i]->isChecked();}o.uvs=uvs_->isChecked();o.flipV=flipV_->isChecked();o.reverseFaces=reverse_->isChecked();o.normals=ExportNormals(normals_->currentIndex());o.material=o.format==ModelFormat::Glb&&material_->isChecked();o.doubleSided=doubleSided_->isChecked();o.color=color_;o.protectedPaths=protectedPaths_;return o;}
void ExportDialog::refresh(){
    auto o=options();bool stl=o.format==ModelFormat::Stl,glb=o.format==ModelFormat::Glb;uvs_->setEnabled(!stl);flipV_->setEnabled(!stl&&uvs_->isChecked());normals_->setEnabled(!stl);material_->setEnabled(glb);colorButton_->setEnabled(glb&&material_->isChecked());doubleSided_->setEnabled(glb&&material_->isChecked());auto selected=selectedMeshes();int stale=0,noUvs=0;for(int i=0;i<entries_.size();++i)if(meshes_->topLevelItem(i)->checkState(0)==Qt::Checked){stale+=entries_[i].stale;noUvs+=!entries_[i].data->hasUvs;}
    QString description=stl?"STL: exports triangles and face normals. Combines meshes into one surface; names, UVs, vertex normals and materials are lost.":glb?"GLB: preserves separate meshes, names, positions, faces and, when enabled, normals, UVs and a matte color material.":"OBJ: preserves separate objects, names, positions, faces and, when enabled, normals and UVs. This exporter does not generate MTL materials.";
    description+=QString("\n%1 meshes selected. Output XYZ = input %2 × %3; selected axis signs are applied.").arg(selected.size()).arg(axes_->currentText()).arg(o.scale);
    description+="\nActual coordinates are exported, without the viewer framing transform. Reflections automatically correct face winding. Geometry is not reduced.";
    description+=glb?"\nGLB uses meters and Y-up; adjust the scale and axes for your binary.":"\nOBJ/STL do not define physical units: match the scale to the destination application.";
    description+="\nThis version does not export textures, bones, animations, debug gradients, offsets or binary formatting rules.";
    if(stale)description+=QString("\nWarning: %1 meshes are previous snapshots of the document.").arg(stale);if(noUvs&&!stl&&o.uvs)description+=QString("\n%1 meshes have no UVs and will be exported without them.").arg(noUvs);summary_->setText(description);save_->setEnabled(!selected.isEmpty()&&!watcher_.isRunning());
}
void ExportDialog::startExport(const QString &path){if(watcher_.isRunning())return;auto meshes=selectedMeshes();if(meshes.isEmpty()){status_->setText("Select at least one mesh.");return;}auto o=options();progress_=std::make_shared<ExportProgress>();auto progress=progress_;settings_->setEnabled(false);save_->setEnabled(false);progressBar_->setValue(0);progressBar_->show();status_->setText("Exporting a snapshot of the selected meshes…");watcher_.setFuture(QtConcurrent::run(&pool_,[path,meshes,o,progress]{return exportModel(path,meshes,o,progress);}));}
